// แยกรายการเครื่องที่ ping ได้ + MAC แล้วลองต่อ port ที่ใช้กับ PLC / HMI
const PORTS = [502, 5000, 5001, 5002, 5015, 5562, 102, 80, 8000, 44818];
const TMO = 800;
const txt = String(msg.payload || "");
const up = new Set((txt.match(/UP (\d+\.\d+\.\d+\.\d+)/g) || []).map(s => s.slice(3)));
const mac = {};
txt.split("\n").forEach(l => { const m = l.match(/^(\d+\.\d+\.\d+\.\d+) .*lladdr ([0-9a-f:]{17})/i); if (m) { mac[m[1]] = m[2]; up.add(m[1]); } });
const self = (txt.match(/inet (\d+\.\d+\.\d+\.\d+)/) || [])[1];
if (self) up.delete(self);
const hosts = [...up].sort((a, b) => +a.split(".")[3] - +b.split(".")[3]);
node.status({ fill: "blue", shape: "ring", text: "พบ " + hosts.length + " เครื่อง กำลังเช็ค port..." });

function probe(h, p) {
    return new Promise(res => {
        const s = new net.Socket(); let f = false;
        const end = r => { if (f) return; f = true; s.destroy(); res(r); };
        s.setTimeout(TMO);
        s.once("connect", () => end(true)); s.once("timeout", () => end(false)); s.once("error", () => end(false));
        s.connect(p, h);
    });
}
(async () => {
    const rows = [];
    await Promise.all(hosts.map(async h => {
        const open = [];
        for (const p of PORTS) if (await probe(h, p)) open.push(p);
        let guess = "";
        if (open.includes(502) || open.includes(5000) || open.includes(5001) || open.includes(5002)) guess = "อ่านได้ (SLMP/Modbus?)";
        else if (open.includes(5015)) guess = "น่าจะเป็นจอ GOT";
        else if (open.includes(5562)) guess = "MELSOFT (PLC ยังไม่เปิด SLMP?)";
        else if (!open.length) guess = "ไม่มี port เปิด (PLC ยังไม่ตั้ง SLMP / อุปกรณ์อื่น)";
        rows.push({ ip: h, mac: mac[h] || "-", open: open.join(", ") || "-", guess });
    }));
    rows.sort((a, b) => +a.ip.split(".")[3] - +b.ip.split(".")[3]);
    node.status({ fill: "green", shape: "dot", text: "พบ " + rows.length + " เครื่องในวง 192.168.0.x" });
    node.send({ topic: "อุปกรณ์ในวง 192.168.0.x (กล่องนี้ = " + (self || "?") + ")", payload: rows });
})();
return null;
